cases.selection-dev-coding-bounds:
def bounds(values):
    if not values:
        raise ValueError("empty")
    return min(values), max(values)

cases.selection-coding-delays:
def retry_delays(start, count, cap):
    if start < 0 or count < 0 or cap < 0:
        raise ValueError("negative")
    return [min(start * 2**i, cap) for i in range(count)]

cases.selection-coding-chunks:
def split_chunks(items, size):
    if size <= 0:
        raise ValueError("size")
    return [items[i:i+size] for i in range(0,len(items),size)]

cases.selection-coding-pairs:
def parse_pairs(text):
    result={}
    for line in text.split("\n"):
        if not line.strip():
            continue
        if ":" not in line:
            raise ValueError("missing colon")
        key,value=line.split(":",1)
        key=key.strip()
        if not key:
            raise ValueError("empty key")
        result[key]=value.strip()
    return result
